// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // bound amount to a reasonable range (1 to 1e18 for example)
        amount = bound(amount, 1, 1e18);
        // call AdjustBetAmounts (regardless of revert)
        c.AdjustBetAmounts(amount);
        // General rule: the public getter currentBetLimit returns the amount set
        assertTrue(c.currentBetLimit() == amount);
    }
}

